function inQuad(x,y,p){let hit=false;for(let i=0,j=3;i<4;j=i++)if((p[i][1]>y)!==(p[j][1]>y)&&x<(p[j][0]-p[i][0])*(y-p[i][1])/(p[j][1]-p[i][1])+p[i][0])hit=!hit;return hit;}
function pick(x,y){projection=projectAll();for(let i=projection.length-1;i>=0;i--){const o=projection[i];if(!inQuad(x,y,o.p))continue;const a=o.p[0],u=o.p[1].map((v,i)=>v-a[i]),v=o.p[3].map((v,i)=>v-a[i]),det=u[0]*v[1]-u[1]*v[0];if(Math.abs(det)<.01)continue;const dx=x-a[0],dy=y-a[1],fu=(dx*v[1]-dy*v[0])/det,fv=(u[0]*dy-u[1]*dx)/det,f=o.f,raw=f.p[0].slice();raw[f.u]+=fu*f.w;raw[f.v]+=fv*f.h;raw[f.axis]-=f.sign*.001;const cell=raw.map(v=>Math.floor(v)+1);if(cell.every(v=>v>=1&&v<=N))return{id:o.id,cell,f};}return null;}
function editMap(){return $('part').value==='head'&&$('patch').value!=='base'?layers.expressions[$('patch').value]:layers.parts[$('part').value];}
function editCell(cell,erase=false,remember=true){if(!cell.every(v=>Number.isInteger(v)&&v>=1&&v<=N))throw Error('XYZ 必須是1～'+N+'的整數');const m=editMap(),key=V.key(...cell,N),patch=$('part').value==='head'&&$('patch').value!=='base';if($('part').value==='head'){try{C.assertFeatureEdit(layers.expressions,$('patch').value,key);$('faceConflict').classList.add('hidden');$('faceConflict').textContent='';}catch(e){$('faceConflict').textContent=e.message;$('faceConflict').classList.remove('hidden');throw e;}}if(remember)record();if(erase){if(patch)m.set(key,-1);else m.delete(key);}else{const c=$('color').value.toLowerCase();let at=project.palette.indexOf(c);if(at<0){if(project.palette.length>=256)throw Error('最多256色');at=project.palette.length;project.palette.push(c);palette();}m.set(key,at);}rebuild($('part').value);}
function selectCell(id,cell){if(!C.IDS.includes(id)||!cell.every(v=>Number.isInteger(v)&&v>=1&&v<=N))return;selected={id,cell:cell.slice()};$('part').value=id;$('patchRow').classList.toggle('hidden',id!=='head');for(let i=0;i<3;i++)$(['cellX','cellY','cellZ'][i]).value=cell[i];if(id!=='head'){$('limb').value=id;syncLimb();}const exists=(id==='head'?headMap():layers.parts[id]).has(V.key(...cell,N));$('selectionInfo').textContent=C.LABEL[id]+' · ('+cell.join(', ')+')'+(exists?' · 改色直接套用':' · 空格，選色即可新增');requestRender();}
function applySelectedColor(){if(!maker||!selected)return;try{editCell(selected.cell,false);selectCell(selected.id,selected.cell);}catch(e){toast(e.message);}}
function editHit(hit){if(!hit)return;if(hit.id!==$('part').value){toast('請先選擇 '+(C.LABEL[hit.id]||'固定軀幹'));return;}const cell=hit.cell.slice();if(tool==='add')cell[hit.f.axis]+=hit.f.sign;selectCell(hit.id,cell);if(tool==='pick'){$('color').value=project.palette[hit.f.color];return;}try{editCell(cell,tool==='erase');}catch(e){toast(e.message);}}

let drag=null,touches=new Map(),pinch=0;canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);touches.set(e.pointerId,[e.clientX,e.clientY]);drag={button:e.button,x:e.clientX,y:e.clientY,sx:e.clientX,sy:e.clientY,moved:false};if(maker&&e.button===0&&tool!=='orbit'){const r=canvas.getBoundingClientRect();editHit(pick(e.clientX-r.left,e.clientY-r.top));}});canvas.addEventListener('pointermove',e=>{if(!drag)return;touches.set(e.pointerId,[e.clientX,e.clientY]);if(touches.size===2){const[a,b]=[...touches.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinch)camera.zoom=Math.max(.3,Math.min(5,camera.zoom*d/pinch));pinch=d;drag.moved=true;requestRender();return;}const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(Math.hypot(e.clientX-drag.sx,e.clientY-drag.sy)>3)drag.moved=true;if(drag.button===1)camera.zoom=Math.max(.3,Math.min(5,camera.zoom*Math.exp(-dy*.012)));else if(drag.button===2||(!maker&&drag.moved)||(maker&&tool==='orbit')){camera.theta+=dx*.008;camera.elev=Math.max(-1.2,Math.min(1.2,camera.elev+dy*.008));}requestRender();});canvas.addEventListener('pointerup',e=>{const d=drag;touches.delete(e.pointerId);if(d&&!d.moved&&d.button===0&&maker&&tool==='orbit'){const r=canvas.getBoundingClientRect(),hit=pick(e.clientX-r.left,e.clientY-r.top);if(hit)selectCell(hit.id,hit.cell);}if(d&&!d.moved&&d.button===0&&!maker){const r=canvas.getBoundingClientRect();if(pick(e.clientX-r.left,e.clientY-r.top))$('panel').classList.toggle('open');else $('panel').classList.remove('open');}drag=null;pinch=0;});canvas.addEventListener('pointercancel',()=>{drag=null;touches.clear();pinch=0;});canvas.addEventListener('wheel',e=>{e.preventDefault();camera.zoom=Math.max(.3,Math.min(5,camera.zoom*Math.exp(-e.deltaY*.001)));requestRender();},{passive:false});
function setState(s,manual=false){if(s.eyes){s.leftEye=s.rightEye=s.eyes;delete s.eyes;}if(s.brow){s.leftBrow=s.rightBrow=s.brow;delete s.brow;}if(manual&&$('source').value!=='manual'){$('source').value='manual';changeSource();}if(s.head)s.head=s.head.map((v,i)=>Math.max(-[35,45,35][i],Math.min([35,45,35][i],Number(v)||0)));state=C.faceState({...state,...s});syncState();requestRender();}
function patchPreview(){$('faceConflict').classList.add('hidden');$('faceConflict').textContent='';if($('part').value!=='head')return;$('patchRow').classList.remove('hidden');const s=C.faceState(),id=$('patch').value;if(id==='eyeLeftHalf')s.leftEye='half';if(id==='eyeLeftClosed')s.leftEye='closed';if(id==='eyeRightHalf')s.rightEye='half';if(id==='eyeRightClosed')s.rightEye='closed';if(id.startsWith('mouth'))s.mouth={mouthOpen:'open',mouthSlight:'slight',mouthSmile:'smile',mouthFrown:'frown'}[id];if(id==='browLeftRaised')s.leftBrow='raised';if(id==='browRightRaised')s.rightBrow='raised';setState(s,true);}
function background(){const solid=$('background').value==='solid';$('stage').classList.toggle('transparent',!solid);$('stage').style.background=solid?$('backgroundColor').value:'';document.body.style.background=maker?'':solid?$('backgroundColor').value:'transparent';}
function install(d,remember=false){d=C.legacy(d);const validated=C.validate(d);if(remember)record();stopInput();project=C.initRig(C.clone(d));layers=validated;N=d.size;unitScale=N/128;selected=null;state=C.faceState(d.defaults);if(!Array.isArray(state.head)||state.head.length!==3)state.head=[0,0,0];state.head=state.head.map((v,i)=>Number.isFinite(v)?Math.max(-[35,45,35][i],Math.min([35,45,35][i],v)):0);$('resolution').value=String(N);$('resolutionLabel').textContent=N+' · FACE + HEAD';for(const id of ['cellX','cellY','cellZ']){$(id).max=N;$(id).value=Math.min(N,Number($(id).value)||1);}for(let i=0;i<3;i++)$('pivot'+i).max=N;$('name').value=project.name;$('modelLabel').textContent=project.name;$('source').value='manual';$('cameraBox').classList.add('hidden');$('vmcBox').classList.add('hidden');$('backgroundColor').value=d.background||'#eee8f3';const s=d.settings||{};$('holdMissingPose').checked=s.holdMissingPose!==false;$('poseLockScope').value=['all','limbs','torso',...C.IDS.filter(id=>id!=='head')].includes(s.poseLockScope)?s.poseLockScope:'all';$('captureMode').value=s.captureMode==='full'?'full':'face';$('gain').value=s.gain||1;$('gainOut').textContent=Number($('gain').value).toFixed(2);$('mirror').checked=!!s.mirror;for(let i=0;i<3;i++)$('invert'+i).checked=!!s.invert?.[i];for(const[key,out,def]of [['eyeHalfThreshold','eyeHalfOut',.25],['eyeClosedThreshold','eyeClosedOut',.65],['browThreshold','browThresholdOut',.25]]){$(key).value=Number.isFinite(s[key])?s[key]:def;$(out).textContent=Number($(key).value).toFixed(2);}$('headScale').value=s.headScale||1;$('headScaleOut').textContent=Number($('headScale').value).toFixed(2);$('showTorso').checked=s.showTorso!==false;$('showHead').checked=s.showHead!==false;$('showPivot').checked=!!s.showPivot;$('showHeadPivot').checked=!!s.showHeadPivot;$('solo').checked=false;$('faceConflict').classList.add('hidden');$('faceConflict').textContent='';$('part').value='head';$('patch').value='base';$('limb').value='leftHand';const e=d.editor||{};$('rigGuides').checked=e.rigGuides!==false;setGrid(!!e.grid);$('hideFeatures').checked=!!e.hideFeatures;for(const axis of 'XYZ'){const id='grid'+axis;$(id).checked=!!e[id];$(id+'Mode').value=e[id+'Mode']==='all'?'all':'single';$(id+'Color').value=e[id+'Color']||{X:'#c96479',Y:'#73a386',Z:'#799ac7'}[axis];$(id+'Opacity').value=Number.isFinite(e[id+'Opacity'])?Math.max(0,Math.min(100,e[id+'Opacity'])):65;$(id+'OpacityOut').textContent=$(id+'Opacity').value+'%';}$('gridColor').value=e.gridColor||'#b6a3c4';$('axesVisible').checked=e.axes!==false;$('axesColor').value=e.axesColor||'#d25885';$('fadeOutside').checked=!!e.fade;$('fadeAmount').value=Number.isFinite(e.fadeAmount)?e.fadeAmount:70;$('fadeAmountOut').textContent=$('fadeAmount').value+'%';$('selectionInfo').textContent='點選角色方格，或輸入XYZ選取位置。改色即套用／新增。';const output=C.exportSettings(d);$('exportTitle').value=output.tabTitle;$('exportName').value=output.filename;$('animateTitle').checked=output.animateTitle;$('titleFormat').value=output.titleFormat;$('titleFrames').value=output.titleFrames.join('\n');$('titleInterval').value=output.titleInterval;startTitleAnimation();loadReferenceImages();palette();syncLimb();syncState();syncRig();rebuild();background();note('目前使用手動');refreshDetectionInfo();}
function clearModel(){record();const empty=C.clone(project);empty.torso.runs=[];for(const id of C.IDS){empty.parts[id].runs=[];empty.parts[id].rotation=[0,0,0];}empty.expressions=Object.fromEntries(C.EX.map(id=>[id,[]]));empty.defaults=C.faceState();empty.name='新 Q版角色';install(empty);toast('已清除全部參考模型與表情，可復原或重新載入參考');}
function download(data,name,type){const b=data instanceof Blob?data:new Blob([data],{type}),a=document.createElement('a'),url=URL.createObjectURL(b);a.href=url;a.download=name;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function html(){const d=serialize();d.references=[];d.settings.showPivot=false;d.settings.showHeadPivot=false;C.validate(d);const doc=document.documentElement.cloneNode(true);for(const el of doc.querySelectorAll('script'))if(!['projectData','referenceData','vmcData','coreCode','appCode'].includes(el.id))el.remove();doc.querySelector('body').dataset.mode='player';doc.querySelector('title').textContent=d.export.tabTitle;for(const selector of ['meta[property="og:title"]','meta[name="twitter:title"]','meta[name="application-name"]'])doc.querySelector(selector)?.setAttribute('content',d.export.tabTitle);doc.querySelector('meta[name="description"]')?.setAttribute('content','3D格子角色展示，支援面部與頭部偵測及手動角色姿勢。');doc.querySelector('#projectData').textContent=JSON.stringify(d).replace(/</g,'\\u003c');doc.querySelector('#referenceData').textContent='null';doc.querySelector('#gpuView')?.remove();doc.querySelector('#referenceView')?.remove();doc.querySelector('#panel').classList.remove('open');doc.querySelector('#vmcFrame').removeAttribute('srcdoc');doc.querySelector('#vmcFrame').setAttribute('src','about:blank');doc.querySelector('#vmcDialog').removeAttribute('open');for(const el of doc.querySelectorAll('.detection-info dd')){el.textContent='—';el.removeAttribute('data-valid');}doc.querySelector('#lockPose').disabled=false;doc.querySelector('#lockPose').textContent='3 秒後鎖定姿勢';doc.querySelector('#poseLockStatus').textContent='尚未鎖定；臉部與頭部持續追蹤';doc.querySelector('#palette').replaceChildren();doc.querySelector('#toast').textContent='';doc.querySelector('#toast').style.display='none';doc.querySelector('#outputTab').textContent='畫面設定';doc.querySelector('#inputTab').textContent='輸入';return'<!doctype html>\n'+doc.outerHTML;}
function glb(){const groups=getGroups(false);if(!groups.some(g=>g.faces.length))throw Error('模型為空，請先建立或載入模型');return C.glb(groups,project.palette,{name:project.name,expression:{leftEye:state.leftEye,rightEye:state.rightEye,mouth:state.mouth,leftBrow:state.leftBrow,rightBrow:state.rightBrow},headAngles:state.head,voxelResolution:N});}
function exportAll(){try{const base=outputBase(),json=JSON.stringify(serialize(),null,2),binary=glb(),runtime=html();const data=C.zip([{name:base+'.html',data:runtime},{name:base+'.glb',data:binary},{name:base+'.json',data:json},{name:'README.txt',data:'HTML：可執行透明角色頁。JSON：可再次匯入製作頁，含五部位、支點與手動旋轉。GLB：目前姿勢／表情的定型模型，不含面捕程式。'}]);download(data,base+'.zip','application/zip');toast('已綜合輸出 HTML＋GLB＋JSON');}catch(e){toast('匯出失敗：'+e.message);}}
// Face/head input only. Limb rotations and pivots are never written here.
let stream=null,tracker=null,tracking=false,generation=0,lastVideo=-1,lastDetect=0,latest=0,raw=[0,0,0],center=[0,0,0],smooth=[0,0,0],browZero=[0,0],lastBrow=[0,0],calTimer=null,countdown=0,inputLost=false;
function cancelCalibration(){if(calTimer!==null)clearInterval(calTimer);calTimer=null;countdown=0;$('calibrate').disabled=false;$('calibrate').textContent='校正歸零（3 秒後）';}
function stopInput(){clearBody();if(bodyTracker){try{bodyTracker.close();}catch{}bodyTracker=null;}generation++;tracking=false;cancelCalibration();if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}if(tracker){try{tracker.close();}catch{}tracker=null;}$('video').srcObject=null;$('startCamera').disabled=false;$('vmcFrame').removeAttribute('srcdoc');$('vmcFrame').src='about:blank';if($('vmcDialog').open)$('vmcDialog').close();latest=0;refreshDetectionInfo();}
// Raw camera frames are never presented. Keep hook for capture compatibility.
function drawBodySkeleton(){}
function refreshDetectionInfo(){
 const now=performance.now(),source=$('source').value,manual=source==='manual',full=source==='camera'&&$('captureMode').value==='full',faceFresh=!!latest&&now-latest<1600;
 const put=(id,value,valid)=>{const el=$('detect'+id);if(!el)return;el.textContent=value;el.setAttribute('data-valid',String(!!valid));};
 put('Input',manual?'手動模式':source==='vmc'?'VMC 臉部／頭部':tracking?'鏡頭運作中':latest?'測試資料':'鏡頭未啟動',manual||tracking||faceFresh);
 put('Face',manual?'手動狀態':faceFresh?'已辨識':latest?'訊號中斷／已復位':'尚未辨識',manual||faceFresh);
 const visible=manual||faceFresh;
 const labels={open:'睜眼',half:'微睜眼',closed:'閉眼',slight:'微張',smile:'閉嘴嘴角上',frown:'閉嘴嘴角下',normal:'復位',raised:'抬高'};
 for(const[id,key]of [['LeftEye','leftEye'],['RightEye','rightEye'],['LeftBrow','leftBrow'],['RightBrow','rightBrow']])put(id,visible?labels[state[key]]:'—',visible);
 put('Mouth',visible?(state.mouth==='open'?'張嘴':labels[state.mouth]):'—',visible);
 for(const[id,i]of [['Pitch',0],['Yaw',1],['Roll',2]])put(id,visible?Math.round(state.head[i])+'°':'—',visible);
 const bodyFresh=full&&!!bodyLatest&&now-bodyLatest<1200;
 put('Torso',poseLocks.torso?'已鎖定':manual?'手動姿勢':!full?(source==='vmc'?'VMC 未支援身體':'未啟用全身'):bodyFresh?(bodyFrame?.torsoValid?'已辨識':'沿用／暫定基準'):$('holdMissingPose').checked&&heldTorso?'未辨識／維持上一姿勢':'尚未辨識／已逾時',manual||bodyFresh);
 for(const[id,key,joint]of [['LeftHand','leftHand','手肘'],['RightHand','rightHand','手肘'],['LeftFoot','leftFoot','膝蓋'],['RightFoot','rightFoot','膝蓋']]){
  const p=bodyParts[key],valid=full&&!!p&&now-p.at<800,leg=key.endsWith('Foot');
  put(id,poseLocks[key]?'已鎖定':manual?'手動姿勢':!full?'未啟用':valid?(p.value.distalValid?'上段＋'+joint+'已辨識':'上段有效／末端未見'):$('holdMissingPose').checked?(heldLimbs[key]?'未辨識／維持上一姿勢':leg?'未辨識／維持站姿':'未辨識／維持手動姿勢'):leg?'未辨識／維持站姿':'未辨識／遮擋',manual||valid);
 }
}

function clearBody(){cancelPoseCountdown();for(const id of Object.keys(poseLocks))delete poseLocks[id];heldTorso=null;updateLockStatus();drawBodySkeleton();bodyFrame=null;bodyZero=null;bodyOverlay=null;bodyLandmarks=null;bodyLatest=0;for(const id of C.IDS)delete bodyParts[id];for(const id of Object.keys(heldLimbs))delete heldLimbs[id];if($('bodyStatus'))$('bodyStatus').textContent='身體追蹤未啟用';projection=[];requestRender();}
function fullBodyMode(){return $('source').value==='camera'&&$('captureMode').value==='full';}
function effectiveOverlay(){return poseLocks.torso?poseLocks.torso.overlay:bodyOverlay||(fullBodyMode()&&$('holdMissingPose').checked?heldTorso?.overlay:null);}
function effectiveBody(){return poseLocks.torso?poseLocks.torso.matrix:C.chain(effectiveOverlay()?C.around(project.torso.pivot,effectiveOverlay()):C.identity(),C.matrix(project.torso.pivot,project.torso.rotation));}
function cancelPoseCountdown(){if(poseLockTimer!==null)clearInterval(poseLockTimer);poseLockTimer=null;poseLockCountdown=0;$('lockPose').disabled=false;$('lockPose').textContent='3 秒後鎖定姿勢';}
function updateLockStatus(){const ids=Object.keys(poseLocks);$('poseLockStatus').textContent=ids.length?'已鎖定：'+ids.map(id=>id==='torso'?'軀幹':C.LABEL[id]).join('、')+'；臉部與頭部持續追蹤':'尚未鎖定；臉部與頭部持續追蹤';}
function capturePoseLock(scope){
 const ids=scope==='all'?['torso',...C.IDS.filter(id=>id!=='head')]:scope==='limbs'?C.IDS.filter(id=>id!=='head'):[scope],snapshot=getGroups(false),overlay=effectiveOverlay();
 const next={};for(const id of ids){if(id==='torso'){next.torso={matrix:C.clone(effectiveBody()),overlay:overlay?overlay.slice():null};continue;}
  const upper=snapshot.find(g=>g.id===id&&g.segment!=='lower'),lower=snapshot.find(g=>g.id===id&&g.segment==='lower');if(!upper)continue;
  next[id]={upper:C.clone(upper.matrix),lower:C.clone(lower?.matrix||upper.matrix)};
 }Object.assign(poseLocks,next);projection=[];updateLockStatus();refreshDetectionInfo();requestRender();
}
$('holdMissingPose').onchange=()=>{dirty=true;projection=[];refreshDetectionInfo();requestRender();};
$('poseLockScope').onchange=()=>{dirty=true;};
$('lockPose').onclick=()=>{cancelPoseCountdown();const scope=$('poseLockScope').value;poseLockCountdown=3;$('lockPose').disabled=true;$('lockPose').textContent='鎖定倒數 3 秒';$('poseLockStatus').textContent='倒數 3 秒，請擺好姿勢；臉部不鎖定';poseLockTimer=setInterval(()=>{poseLockCountdown--;if(poseLockCountdown>0){$('lockPose').textContent='鎖定倒數 '+poseLockCountdown+' 秒';$('poseLockStatus').textContent='倒數 '+poseLockCountdown+' 秒，請擺好姿勢';return;}cancelPoseCountdown();capturePoseLock(scope);},1000);};
$('unlockPose').onclick=()=>{cancelPoseCountdown();for(const id of Object.keys(poseLocks))delete poseLocks[id];updateLockStatus();projection=[];refreshDetectionInfo();requestRender();};
function holdLimbPose(id,value){
 const p=project.parts[id],body=effectiveBody();
 const upper=C.chain(body,C.chain(C.around(p.pivot,value.upper),C.matrix(p.pivot,p.rotation)));
 const bend=p.bend?C.chain(C.around(p.bend.pivot,value.lower),C.matrix(p.bend.pivot,p.bend.rotation)):C.identity();
 heldLimbs[id]={upper:C.clone(upper),lower:C.chain(upper,bend)};
}
function ingestBody(points){if($('captureMode').value!=='full')return;const now=performance.now();for(const id of C.IDS)if(id!=='head')delete bodyParts[id];if(points?.length>=33){bodyLandmarks=points.map((p,i)=>{const prior=bodyLandmarks?.[i],valid=[p.x,p.y,p.z].every(Number.isFinite);return valid?{...p,x:prior?prior.x*.55+p.x*.45:p.x,y:prior?prior.y*.55+p.y*.45:p.y,z:prior?prior.z*.55+p.z*.45:p.z}:p;});const solved=C.solveBody(bodyLandmarks,project,$('mirror').checked,bodyFrame?.torso);if(solved){bodyFrame=solved;bodyLatest=now;bodyOverlay=bodyZero?C.mm(solved.torso,C.transpose(bodyZero)):solved.torso;if(solved.torsoValid)heldTorso={overlay:bodyOverlay.slice()};for(const[id,value]of Object.entries(solved.parts)){const leg=id==='leftFoot'||id==='rightFoot';if(!value.distalValid&&(leg||$('holdMissingPose').checked))continue;bodyParts[id]={value,at:now};holdLimbPose(id,value);}$('bodyStatus').textContent='身體追蹤：'+Object.keys(solved.parts).filter(id=>bodyParts[id]).map(id=>C.LABEL[id]+(solved.parts[id].distalValid?'✓':'（末端未見）')).join('、')+'；'+(solved.torsoValid?'軀幹有效':'軀幹沿用／暫定');}else $('bodyStatus').textContent='收到身體資料，但關節不清楚：請讓肩膀與手肘入鏡（不必先拍到腳）';}else $('bodyStatus').textContent='全身模型運作中，但未找到人體；請退後並增加光線';for(const[id,p]of Object.entries(bodyParts))if(now-p.at>800)delete bodyParts[id];projection=[];requestRender();}
$('limbBendEnabled').onchange=()=>{record();project.parts[$('limb').value].bend.enabled=$('limbBendEnabled').checked;syncRig();projection=[];requestRender();};
